    Pair* First;
    Pair* Last;
    Pair* LowerBound(const int& key)
    {
        Pair* first = First;
        long count = (long)(Last - First);
        while (count > 0) {
            long half = count >> 1;
            if (first[half].first < key) { first += half + 1; count -= half + 1; }
